@Observable final class Player {
    var title = ""
    var progress = 0.0                 // changes 60 times per second
    @ObservationIgnored var task: Task<Void, Never>?
}

struct TitleView: View {
    let player: Player
    var body: some View { Text(player.title) }          // not affected by progress
}

struct ProgressBar: View {
    let player: Player
    var body: some View { ProgressView(value: player.progress) }
}
